import{_ as r,o as e,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"マーケットプレイス（Supermarket）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/supermarket.md","filePath":"ja/guides/supermarket.md","lastUpdated":1792323081000}'),s={name:"ja/guides/supermarket.md"};function n(l,t,d,i,g,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="マーケットプレイス-supermarket" tabindex="-1">マーケットプレイス（Supermarket） <a class="header-anchor" href="#マーケットプレイス-supermarket" aria-label="Permalink to &quot;マーケットプレイス（Supermarket）&quot;">​</a></h1><p>マーケットプレイスは Memoh 内蔵のアプリカタログです。ここでいう<strong>アプリ（App）<strong>はパッケージ化された機能の単位で、1 つの App には複数の</strong>スキル</strong>（再利用可能な手順の説明）、<strong>依存関係</strong>（ワークスペースにインストールされるツール）、そして<strong>コネクター</strong>（GitHub や Notion といったサードパーティサービスとの連携）を含められます。インストールするのは App 全体なので、スキルやコネクターを別々に探す必要はありません。</p><p>クライアントのサイドバーから <strong>マーケットプレイス</strong> を開きます。アプリはカテゴリー別に並び、検索やタグでの絞り込みができます。詳細ページでは、アプリの説明、コンポーネント構成（スキル・依存関係・コネクターの数）、作者、バージョン、提供元 Registry、リンクを確認できます。</p><hr><h2 id="アプリをインストールする" tabindex="-1">アプリをインストールする <a class="header-anchor" href="#アプリをインストールする" aria-label="Permalink to &quot;アプリをインストールする&quot;">​</a></h2><ol><li><strong>マーケットプレイス</strong> でアプリを選び、詳細ページを開きます。</li><li><strong>Botにインストールする</strong> をクリックし、対象の Bot を選びます。</li><li>アプリが環境変数を宣言している場合は、必要な値を先に入力します。</li><li>インストールを確定します。</li></ol><p>インストールと更新には、その Bot のワークスペースが実行中である必要があります。スキルはワークスペースに書き込まれ、依存関係はワークスペースにインストールされ、コネクターは連携が確立されます。インストール中は進捗が表示され、中断した場合は <strong>セットアップを続行</strong> または <strong>インストールを復元</strong> で再開できます。</p><hr><h2 id="インストール後-bot-の「アプリ」タブ" tabindex="-1">インストール後：Bot の「アプリ」タブ <a class="header-anchor" href="#インストール後-bot-の「アプリ」タブ" aria-label="Permalink to &quot;インストール後：Bot の「アプリ」タブ&quot;">​</a></h2><p>Bot 詳細ページの <strong>アプリ</strong> タブには、インストール済みの App がコンポーネント別のステータスとともに一覧表示されます。</p><table tabindex="0"><thead><tr><th>コンポーネント</th><th>行き先</th></tr></thead><tbody><tr><td><strong>スキル</strong></td><td>ワークスペースの管理対象ディレクトリ <code>/data/skills/&lt;registry&gt;/&lt;app&gt;/</code> に書き込まれ、アプリが管理します——更新・アンインストール時に一緒に処理されるため、手動で変更しないでください（<a href="./skills.html">スキル</a> を参照）</td></tr><tr><td><strong>依存関係</strong></td><td>その Bot のワークスペースにインストールされ、同じワークスペース内でそれらを必要とする他のアプリと共有されます</td></tr><tr><td><strong>コネクター</strong></td><td><strong>認証が必要</strong>・<strong>任意</strong>・<strong>全ワークスペースで共有</strong> のいずれかが表示されます。<strong>認証する</strong> をクリックして OAuth を完了するか、API Key を入力します（<a href="./../self-hosted/connectors.html">コネクター</a> を参照）</td></tr></tbody></table><p>よく使う操作：<strong>更新を確認</strong>、<strong>更新</strong>、<strong>アンインストール</strong>。一部のコンポーネントが失敗したり未認証のままだったりすると、アプリは「要対応」と表示されます。コンポーネント一覧を開いて設定を済ませてください。</p><hr><h2 id="カタログの提供元" tabindex="-1">カタログの提供元 <a class="header-anchor" href="#カタログの提供元" aria-label="Permalink to &quot;カタログの提供元&quot;">​</a></h2><p>マーケットプレイスのコンテンツは上流の Registry から提供され、デフォルトは <code>supermarket.memoh.ai</code> です。セルフホストのインスタンスでは <code>supermarket.base_url</code> を別の信頼できるカタログに向けられます。設定リファレンスは <a href="./../self-hosted/docker.html">Server Deploy</a> を参照してください。</p><hr><h2 id="コントリビューション" tabindex="-1">コントリビューション <a class="header-anchor" href="#コントリビューション" aria-label="Permalink to &quot;コントリビューション&quot;">​</a></h2><p>新しいアプリは次へ提出できます。</p><ul><li><a href="https://github.com/felinics/supermarket" target="_blank" rel="noreferrer">felinics/supermarket</a></li></ul>',19)])])}const c=r(s,[["render",n]]);export{u as __pageData,c as default};
